import { sql } from "drizzle-orm";
import {
  bigint,
  bigserial,
  boolean,
  check,
  customType,
  date,
  doublePrecision,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  unique,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const createdAt = () => timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

// ---------------------------------------------------------------------------
// Better-Auth 1.7.x tables (text ids, generated by Better-Auth). Columns follow
// the core schema plus the twoFactor plugin; verified against
// @better-auth/core get-tables and better-auth/plugins/two-factor/schema.
// ---------------------------------------------------------------------------
export const users = pgTable("users", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  twoFactorEnabled: boolean("two_factor_enabled").default(false),
  /** When this person first saw the one-time notice about what AI features send to Anthropic. Null until they do. */
  aiNoticeSeenAt: timestamp("ai_notice_seen_at", { withTimezone: true }),
  createdAt: createdAt(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const sessions = pgTable(
  "sessions",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    token: text("token").notNull().unique(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("sessions_user_id_idx").on(t.userId)],
);

export const accounts = pgTable(
  "accounts",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    scope: text("scope"),
    password: text("password"),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("accounts_user_id_idx").on(t.userId)],
);

export const verifications = pgTable(
  "verifications",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("verifications_identifier_idx").on(t.identifier)],
);

export const twoFactors = pgTable(
  "two_factors",
  {
    id: text("id").primaryKey(),
    secret: text("secret").notNull(),
    backupCodes: text("backup_codes").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    verified: boolean("verified").default(true),
    failedVerificationCount: integer("failed_verification_count").default(0),
    lockedUntil: timestamp("locked_until", { withTimezone: true }),
  },
  (t) => [
    index("two_factors_secret_idx").on(t.secret),
    index("two_factors_user_id_idx").on(t.userId),
  ],
);

// ---------------------------------------------------------------------------
// Tenant tables. Every one except organizations carries org_id NOT NULL.
// ---------------------------------------------------------------------------
export const membershipRole = pgEnum("membership_role", [
  "owner",
  "admin",
  "manager",
  "client_approver",
  "client_viewer",
]);
export const auditSurface = pgEnum("audit_surface", ["ui", "mcp", "worker", "cli"]);

export const organizations = pgTable("organizations", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull(),
  /** First-run checklist: when anyone first opened a location's health report. The report itself is read live from Google, so this is the only trace. */
  healthReportSeenAt: timestamp("health_report_seen_at", { withTimezone: true }),
  /** First-run checklist: when an owner or admin hid the checklist before finishing it. */
  setupDismissedAt: timestamp("setup_dismissed_at", { withTimezone: true }),
  /** An owner switched AI features off for the whole account. While set, no content is sent to Anthropic or OpenAI. */
  aiDisabledAt: timestamp("ai_disabled_at", { withTimezone: true }),
  createdAt: createdAt(),
});

const orgId = () =>
  uuid("org_id")
    .notNull()
    .references(() => organizations.id);

/**
 * BCP 47 codes a post (and a post template) can be written in; sent to Google as
 * LocalPost.languageCode. Names live in core (`POST_LANGUAGES`). en and es first: the pickers show
 * the rest under "Other languages".
 */
export const postLanguages = [
  "en",
  "es",
  "fr",
  "de",
  "it",
  "pt",
  "nl",
  "vi",
  "zh",
  "ko",
  "ja",
  "ar",
  "hi",
  "gu",
] as const;

export const timeZoneSources = ["default", "derived", "manual"] as const;
export const dateFormats = ["YYYY-MM-DD", "DD/MM/YYYY", "MM/DD/YYYY"] as const;

export const workspaces = pgTable(
  "workspaces",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    name: text("name").notNull(),
    /** The language new posts start in (posts.createDraft without a language). */
    defaultPostLanguage: text("default_post_language", { enum: postLanguages })
      .notNull()
      .default("en"),
    /** IANA zone the client's times are shown and scheduled in. Validated by core's isValidTimeZone. */
    timeZone: text("time_zone").notNull().default("UTC"),
    /** default: never chosen (the first location import derives it); derived: from an address; manual: saved in settings. */
    timeZoneSource: text("time_zone_source", { enum: timeZoneSources })
      .notNull()
      .default("default"),
    /** YYYY-MM-DD, DD/MM/YYYY or MM/DD/YYYY. */
    dateFormat: text("date_format", { enum: dateFormats }).notNull().default("YYYY-MM-DD"),
    /** default: never chosen (the first location import derives it from the country); derived: from an address; manual: saved in settings. */
    dateFormatSource: text("date_format_source", { enum: timeZoneSources })
      .notNull()
      .default("default"),
    /** Review request sender identity: the business's legal name and postal address are required before the first send (they appear in every email). */
    senderLegalName: text("sender_legal_name"),
    senderPostalAddress: text("sender_postal_address"),
    /** Company or ABN number, where the business has one. */
    senderCompanyNumber: text("sender_company_number"),
    senderPhone: text("sender_phone"),
    senderWebsite: text("sender_website"),
    /** The business is a HIPAA covered entity: review requests are unavailable and reply auto-approve is locked off. */
    hipaaCoveredEntity: boolean("hipaa_covered_entity").notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [unique("workspaces_org_id_name_unique").on(t.orgId, t.name)],
);

export const locationStatus = ["active", "inactive"] as const;
/** Where a location's stored coordinates came from (locations.center_source). 'manual' is never overwritten automatically. */
export const locationCenterSources = [
  "google",
  "places",
  "dataforseo",
  "tracker",
  "manual",
] as const;

export const locations = pgTable(
  "locations",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    name: text("name").notNull(),
    /** `locations/{l}` (v1). The notification webhook lookup key. */
    googleLocationId: text("google_location_id"),
    /** `accounts/{a}`; reviews (v4) are addressed as accounts/{a}/locations/{l}/reviews/{r}. */
    googleAccountName: text("google_account_name"),
    connectionId: uuid("connection_id").references(() => googleConnections.id, {
      onDelete: "set null",
    }),
    title: text("title"),
    /** Primary phone from Google; used by reply templates. */
    phone: text("phone"),
    addressSummary: text("address_summary"),
    status: text("status", { enum: locationStatus }).notNull().default("active"),
    importedAt: timestamp("imported_at", { withTimezone: true }),
    /** Stored coordinates (resolved once at onboarding; refreshed only when the storefront address changes). Null until resolved. */
    centerLat: doublePrecision("center_lat"),
    centerLng: doublePrecision("center_lng"),
    centerSource: text("center_source", { enum: locationCenterSources }),
    /** Hash of the normalised storefront address the coordinates were resolved for. */
    centerAddressHash: text("center_address_hash"),
    centerUpdatedAt: timestamp("center_updated_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    // One ACTIVE row per Google location across ALL orgs (ambiguous matches are dropped).
    uniqueIndex("locations_google_location_id_active_unique")
      .on(t.googleLocationId)
      .where(sql`${t.status} = 'active' AND ${t.googleLocationId} IS NOT NULL`),
  ],
);

/**
 * One-off DataForSEO calls made on OUR key outside a rank run (such as the onboarding coordinate
 * lookup). Counted with grid_runs toward the platform's daily cap; never charged to a customer.
 */
export const platformDfsSpend = pgTable(
  "platform_dfs_spend",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    kind: text("kind").notNull(),
    locationId: uuid("location_id").references(() => locations.id, { onDelete: "set null" }),
    costUsd: numeric("cost_usd", { precision: 12, scale: 4 }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("platform_dfs_spend_created_idx").on(t.createdAt)],
);

/**
 * A health check someone chose to skip for one location: left out of that location's score until
 * undone. One row per (location, check). `skipped_by` is kept nullable so a user can be deleted.
 */
export const healthcheckSkips = pgTable(
  "healthcheck_skips",
  {
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    checkId: text("check_id").notNull(),
    skippedBy: text("skipped_by").references(() => users.id, { onDelete: "set null" }),
    skippedAt: timestamp("skipped_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.locationId, t.checkId] })],
);

/**
 * A request to import Google locations into a workspace. The action records it and enqueues a
 * pg-boss job in one transaction; the worker calls Google (never inside the action's transaction),
 * inserts the locations and writes `results`. Idempotent: only a `pending` row is processed.
 */
export const locationImports = pgTable("location_imports", {
  id: uuid("id").primaryKey().defaultRandom(),
  orgId: orgId(),
  workspaceId: uuid("workspace_id")
    .notNull()
    .references(() => workspaces.id),
  connectionId: uuid("connection_id").references(() => googleConnections.id, {
    onDelete: "set null",
  }),
  requestedBy: text("requested_by")
    .notNull()
    .references(() => users.id),
  /** [{ accountName, locationName }] as requested; nothing here came from Google. */
  items: jsonb("items").notNull(),
  status: text("status", { enum: ["pending", "done", "failed"] })
    .notNull()
    .default("pending"),
  /** Per-location outcome once processed. */
  results: jsonb("results"),
  createdAt: createdAt(),
  completedAt: timestamp("completed_at", { withTimezone: true }),
});

export const locationGroups = pgTable(
  "location_groups",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    name: text("name").notNull(),
    createdAt: createdAt(),
  },
  (t) => [unique("location_groups_workspace_id_name_unique").on(t.workspaceId, t.name)],
);

export const locationGroupMembers = pgTable(
  "location_group_members",
  {
    groupId: uuid("group_id")
      .notNull()
      .references(() => locationGroups.id, { onDelete: "cascade" }),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    orgId: orgId(),
  },
  (t) => [primaryKey({ columns: [t.groupId, t.locationId] })],
);

export const memberships = pgTable(
  "memberships",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    workspaceId: uuid("workspace_id").references(() => workspaces.id),
    role: membershipRole("role").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    unique("memberships_org_user_workspace_unique")
      .on(t.orgId, t.userId, t.workspaceId)
      .nullsNotDistinct(),
    check(
      "memberships_workspace_iff_client_role",
      sql`(${t.workspaceId} IS NOT NULL) = (${t.role} IN ('client_approver', 'client_viewer'))`,
    ),
  ],
);

export const googleConnections = pgTable(
  "google_connections",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    /** The Google account's OpenID `sub`: stable, unlike the email. */
    googleAccountId: text("google_account_id").notNull(),
    googleAccountEmail: text("google_account_email").notNull(),
    refreshTokenEnc: text("refresh_token_enc").notNull(),
    scopes: text("scopes").array().notNull(),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("google_connections_org_id_google_account_id_unique").on(t.orgId, t.googleAccountId),
  ],
);

/**
 * Server-side OAuth state for the connect flow. The row is the state: single use (used_at),
 * short lived (expires_at), bound to the user and org that started it, and holds the PKCE verifier.
 */
export const googleOauthStates = pgTable("google_oauth_states", {
  /** 32 random bytes, base64url. */
  id: text("id").primaryKey(),
  orgId: orgId(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id),
  codeVerifier: text("code_verifier").notNull(),
  createdAt: createdAt(),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  usedAt: timestamp("used_at", { withTimezone: true }),
});

export const auditLog = pgTable(
  "audit_log",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    orgId: orgId(),
    actorUserId: text("actor_user_id").references(() => users.id),
    actorType: text("actor_type").notNull(),
    surface: auditSurface("surface").notNull(),
    action: text("action").notNull(),
    entityType: text("entity_type").notNull(),
    entityId: text("entity_id").notNull(),
    before: jsonb("before"),
    after: jsonb("after"),
    // Set by app code (ms precision) so the hashed value equals the stored value.
    createdAt: timestamp("created_at", { withTimezone: true, precision: 3 }).notNull(),
    prevHash: text("prev_hash"),
    hash: text("hash").notNull(),
  },
  (t) => [
    index("audit_log_org_id_created_at_idx").on(t.orgId, t.createdAt),
    check("audit_log_actor_type_check", sql`${t.actorType} IN ('user', 'api_token', 'system')`),
  ],
);

/**
 * One signed row per org: the audit chain head as of the last audit write. Written in the same
 * transaction (under the same advisory lock) as the audit insert. `signature` is an HMAC with
 * AUDIT_CHECKPOINT_KEY, which the database never sees, so DB-only access cannot forge it.
 */
export const auditCheckpoints = pgTable("audit_checkpoints", {
  orgId: uuid("org_id")
    .primaryKey()
    .references(() => organizations.id),
  lastId: bigint("last_id", { mode: "number" }).notNull(),
  lastHash: text("last_hash").notNull(),
  rowCount: bigint("row_count", { mode: "number" }).notNull(),
  // Set by app code (ms precision) so the signed value equals the stored value.
  updatedAt: timestamp("updated_at", { withTimezone: true, precision: 3 }).notNull(),
  signature: text("signature").notNull(),
});

export const apiTokens = pgTable("api_tokens", {
  id: uuid("id").primaryKey().defaultRandom(),
  orgId: orgId(),
  userId: text("user_id")
    .notNull()
    .references(() => users.id),
  name: text("name").notNull(),
  tokenHash: text("token_hash").notNull().unique(),
  /** 'read' and/or 'write'. Existing tokens keep read+write. Enforced in core (executor), never in MCP code. */
  scopes: text("scopes")
    .array()
    .notNull()
    .default(sql`ARRAY['read','write']::text[]`),
  /** 'human_in_the_loop' (default, also for tokens that predate this setting) or 'full_autonomy'. Enforced in core authorizeAction. */
  mode: text("mode").notNull().default("human_in_the_loop"),
  createdAt: createdAt(),
  lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
  revokedAt: timestamp("revoked_at", { withTimezone: true }),
});

/**
 * Fixed-window counters for the Google API throttler, shared by every process (web, mcp, worker)
 * because the 300 QPM quota is per Cloud project. No org column: buckets are not tenant data
 * (`project`, `location-edit:locations/{id}`).
 */
export const googleRateWindows = pgTable(
  "google_rate_windows",
  {
    bucketKey: text("bucket_key").notNull(),
    windowStart: timestamp("window_start", { withTimezone: true }).notNull(),
    count: integer("count").notNull(),
  },
  (t) => [primaryKey({ columns: [t.bucketKey, t.windowStart] })],
);

/** Write idempotency for Google calls: one row per (org, caller-chosen key). */
export const googleIdempotencyKeys = pgTable(
  "google_idempotency_keys",
  {
    orgId: orgId(),
    key: text("key").notNull(),
    requestHash: text("request_hash").notNull(),
    status: text("status", { enum: ["pending", "done"] }).notNull(),
    response: jsonb("response"),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.orgId, t.key] })],
);

export const googleNotificationType = pgEnum("google_notification_type", [
  "NEW_REVIEW",
  "UPDATED_REVIEW",
  "GOOGLE_UPDATE",
]);

/**
 * Inbound Business Profile notifications delivered through Pub/Sub push. One row per Pub/Sub
 * message (pubsub_message_id is unique, which makes redelivery idempotent). The payload holds the
 * decoded notification as Google sent it; it names resources, it carries no review text.
 * `location_name` is the normalised `locations/{id}` form, the same format as
 * `locations.google_location_id`.
 */
export const googleNotifications = pgTable(
  "google_notifications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    pubsubMessageId: text("pubsub_message_id").notNull().unique(),
    type: googleNotificationType("type").notNull(),
    /** The review resource name for review notifications; null for GOOGLE_UPDATE. */
    resourceName: text("resource_name"),
    locationName: text("location_name").notNull(),
    payload: jsonb("payload").notNull(),
    publishTime: timestamp("publish_time", { withTimezone: true }),
    receivedAt: timestamp("received_at", { withTimezone: true }).notNull().defaultNow(),
    processedAt: timestamp("processed_at", { withTimezone: true }),
  },
  (t) => [index("google_notifications_org_id_received_at_idx").on(t.orgId, t.receivedAt)],
);

/**
 * Per Google account (`accounts/{id}`): did we point its Business Profile notifications at our
 * Pub/Sub topic? One row per account; the latest attempt wins. `registered_at` is set only when
 * Google accepted the setting; `last_error` holds a plain message from the latest failed attempt.
 */
export const googleNotificationRegistrations = pgTable("google_notification_registrations", {
  id: uuid("id").primaryKey().defaultRandom(),
  orgId: orgId(),
  connectionId: uuid("connection_id").references(() => googleConnections.id, {
    onDelete: "set null",
  }),
  accountName: text("account_name").notNull().unique(),
  topic: text("topic"),
  registeredAt: timestamp("registered_at", { withTimezone: true }),
  lastAttemptAt: timestamp("last_attempt_at", { withTimezone: true }).notNull().defaultNow(),
  lastError: text("last_error"),
});

/**
 * In-app notifications. Titles carry the location NAME only, never review text (clinic reviews
 * can contain patient details). Unique on (user_id, source_type, source_id) so re-processing the
 * job that produced one cannot duplicate it.
 */
export const notifications = pgTable(
  "notifications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    /** e.g. google.new_review | google.updated_review | google.google_update */
    kind: text("kind").notNull(),
    title: text("title").notNull(),
    link: text("link"),
    sourceType: text("source_type").notNull(),
    sourceId: text("source_id").notNull(),
    createdAt: createdAt(),
    readAt: timestamp("read_at", { withTimezone: true }),
  },
  (t) => [
    unique("notifications_user_source_unique").on(t.userId, t.sourceType, t.sourceId),
    index("notifications_user_id_org_id_read_at_idx").on(t.userId, t.orgId, t.readAt),
  ],
);

/**
 * One browser or device a person turned push notifications on for (Web Push). `endpoint` is the
 * push service URL and is unique: the same device re-subscribing replaces its row. `p256dh` and
 * `auth` are the public key and secret the browser handed over so the server can encrypt a payload
 * for it. Rows are deleted when the push service answers 404 or 410.
 */
export const pushSubscriptions = pgTable(
  "push_subscriptions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    endpoint: text("endpoint").notNull().unique(),
    p256dh: text("p256dh").notNull(),
    auth: text("auth").notNull(),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
  },
  (t) => [index("push_subscriptions_user_id_org_id_idx").on(t.userId, t.orgId)],
);

/** One row per (org, user, UTC day): the claim that makes the daily email digest idempotent. */
export const notificationDigests = pgTable(
  "notification_digests",
  {
    orgId: orgId(),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    digestDate: date("digest_date").notNull(),
    status: text("status", { enum: ["pending", "sent"] }).notNull(),
    notificationCount: integer("notification_count").notNull(),
    sentAt: timestamp("sent_at", { withTimezone: true }),
  },
  (t) => [primaryKey({ columns: [t.orgId, t.userId, t.digestDate] })],
);

/**
 * A Google review, mirrored from Business Profile (v4). Google is the source of truth, including
 * `reply_comment`: a reply made in the Google UI shows up here after the next sync or Pub/Sub
 * UPDATED_REVIEW. `star_rating` is 1-5, or null for star-less/unspecified. Review text is customer
 * data: it may carry patient details, so it never goes into audit rows or notifications.
 */
export const reviews = pgTable(
  "reviews",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    /** `accounts/{a}/locations/{l}/reviews/{r}` */
    googleReviewName: text("google_review_name").notNull().unique(),
    reviewerDisplayName: text("reviewer_display_name"),
    reviewerIsAnonymous: boolean("reviewer_is_anonymous").notNull().default(false),
    starRating: smallint("star_rating"),
    comment: text("comment"),
    createTime: timestamp("create_time", { withTimezone: true }).notNull(),
    updateTime: timestamp("update_time", { withTimezone: true }).notNull(),
    replyComment: text("reply_comment"),
    replyUpdateTime: timestamp("reply_update_time", { withTimezone: true }),
    /** Google's moderation of the reply ("APPROVED", "REJECTED", ...); null when absent or no reply. */
    replyState: text("reply_state"),
    /** Why Google rejected the reply, e.g. "ACCOUNT_RESTRICTED_AND_EDIT_REJECTED". */
    replyPolicyViolation: text("reply_policy_violation"),
    firstSeenAt: timestamp("first_seen_at", { withTimezone: true }).notNull().defaultNow(),
    syncedAt: timestamp("synced_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("reviews_org_workspace_location_idx").on(t.orgId, t.workspaceId, t.locationId),
    index("reviews_location_unreplied_idx").on(t.locationId, sql`(${t.replyComment} is null)`),
    index("reviews_create_time_idx").on(t.createTime),
    // Search: ILIKE '%x%' on review text and reviewer name uses these (pg_trgm).
    index("reviews_comment_trgm_idx").using("gin", sql`${t.comment} gin_trgm_ops`),
    index("reviews_reviewer_trgm_idx").using("gin", sql`${t.reviewerDisplayName} gin_trgm_ops`),
  ],
);

/**
 * Who a review is assigned to (one row per review). Internal only: client roles never read it.
 * `due_at` is an instant; the assignee must be an org-wide member (checked by the action).
 */
export const reviewAssignments = pgTable(
  "review_assignments",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    reviewId: uuid("review_id")
      .notNull()
      .unique()
      .references(() => reviews.id, { onDelete: "cascade" }),
    assigneeUserId: text("assignee_user_id")
      .notNull()
      .references(() => users.id),
    assignedBy: text("assigned_by")
      .notNull()
      .references(() => users.id),
    dueAt: timestamp("due_at", { withTimezone: true }),
    assignedAt: timestamp("assigned_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("review_assignments_org_assignee_idx").on(t.orgId, t.assigneeUserId)],
);

/**
 * Internal notes on a review. Staff only: never sent to Google, never in reply text, never shown to
 * client roles, and never copied into audit rows or notifications (a note can name a patient).
 */
export const reviewNotes = pgTable(
  "review_notes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    reviewId: uuid("review_id")
      .notNull()
      .references(() => reviews.id, { onDelete: "cascade" }),
    authorUserId: text("author_user_id")
      .notNull()
      .references(() => users.id),
    body: text("body").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("review_notes_review_idx").on(t.reviewId, t.createdAt)],
);

/** One row per requested location sync, so the UI can poll. Counts only; never review text. */
export const reviewSyncs = pgTable("review_syncs", {
  id: uuid("id").primaryKey().defaultRandom(),
  orgId: orgId(),
  locationId: uuid("location_id")
    .notNull()
    .references(() => locations.id, { onDelete: "cascade" }),
  /** Null for the initial sync enqueued by the import job (no requesting user). */
  requestedBy: text("requested_by").references(() => users.id),
  status: text("status", { enum: ["pending", "done", "failed"] })
    .notNull()
    .default("pending"),
  /** { fetched, inserted, updated } once done; { error } when failed. */
  counts: jsonb("counts"),
  error: text("error"),
  createdAt: createdAt(),
  finishedAt: timestamp("finished_at", { withTimezone: true }),
});

/**
 * One row per review the draft-on-arrival job has handled. The primary key is the idempotency
 * guard: a retried or duplicated job finds the row and does nothing, so a review is auto-drafted
 * at most once even if a person rejects the draft. Outcome only; never review or reply text.
 */
export const reviewAutoDrafts = pgTable("review_auto_drafts", {
  reviewId: uuid("review_id")
    .primaryKey()
    .references(() => reviews.id, { onDelete: "cascade" }),
  orgId: orgId(),
  workspaceId: uuid("workspace_id")
    .notNull()
    .references(() => workspaces.id),
  /** drafted | held | blocked | skipped_* (see reviews/draft-on-arrival.ts) */
  outcome: text("outcome").notNull(),
  replyId: uuid("reply_id"),
  createdAt: createdAt(),
});

export const reviewLinkSources = ["link", "qr", "sms", "email"] as const;
export const reviewLinkLayouts = ["grid", "list", "carousel", "badge"] as const;

/**
 * A tracked short link to Google's review form, one per location. `google_place_id` is stored
 * because the public redirect must not call Google. The widget is opt-in (`widget_enabled`).
 */
export const reviewLinks = pgTable(
  "review_links",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    /** Public, unique across all organizations. */
    slug: text("slug").notNull(),
    googlePlaceId: text("google_place_id").notNull(),
    widgetEnabled: boolean("widget_enabled").notNull().default(false),
    /** 1 shows every rating, 4 shows 4 and 5 stars. The widget always states it. */
    widgetMinRating: smallint("widget_min_rating").notNull().default(4),
    widgetLayout: text("widget_layout", { enum: reviewLinkLayouts }).notNull().default("grid"),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("review_links_slug_unique").on(t.slug),
    unique("review_links_location_unique").on(t.locationId),
    check("review_links_min_rating_check", sql`${t.widgetMinRating} between 1 and 5`),
  ],
);

/**
 * The public landing page of one location, served at /l/<slug>. Off by default (`published`);
 * the content is read from stored data at request time, nothing is copied here. The slug is
 * public and unique across all organizations.
 */
export const locationPages = pgTable(
  "location_pages",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    slug: text("slug").notNull(),
    published: boolean("published").notNull().default(false),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    publishedBy: text("published_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("location_pages_slug_unique").on(t.slug),
    unique("location_pages_location_unique").on(t.locationId),
  ],
);

export const citationStatus = ["not_started", "submitted", "live", "needs_fix"] as const;
/** Outcome of the last "check listing" run. could_not_fetch covers bot blocks and every fetch failure; it is never a mismatch. */
export const citationCheckResult = ["match", "mismatch", "not_found", "could_not_fetch"] as const;

/**
 * One row per location and citation site the user has started tracking by hand. `siteKey` names
 * a site in core's config/citation-sites.ts; a custom site has `siteKey` null and its own name and URL.
 * `listingUrl` is kept so a later NAP check can fetch the listing. There is deliberately no
 * password or login column: logins stay in the user's password manager.
 */
export const citationEntries = pgTable(
  "citation_entries",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    siteKey: text("site_key"),
    customName: text("custom_name"),
    customUrl: text("custom_url"),
    status: text("status", { enum: citationStatus }).notNull().default("not_started"),
    listingUrl: text("listing_url"),
    emailUsed: text("email_used"),
    nameUsed: text("name_used"),
    addressUsed: text("address_used"),
    phoneUsed: text("phone_used"),
    submittedOn: date("submitted_on", { mode: "string" }),
    notes: text("notes"),
    /** NAP audit: when the listing was last fetched and compared, the outcome, and per-field detail ({ fields, reason }). */
    checkedAt: timestamp("checked_at", { withTimezone: true }),
    checkResult: text("check_result", { enum: citationCheckResult }),
    checkDetail: jsonb("check_detail").$type<{
      fields?: { name?: string; address?: string; phone?: string };
      reason?: string;
    }>(),
    updatedBy: text("updated_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("citation_entries_location_site_unique")
      .on(t.locationId, t.siteKey)
      .where(sql`${t.siteKey} IS NOT NULL`),
    index("citation_entries_location_idx").on(t.locationId),
    check(
      "citation_entries_site_or_custom_check",
      sql`(${t.siteKey} IS NOT NULL AND ${t.customName} IS NULL AND ${t.customUrl} IS NULL) OR (${t.siteKey} IS NULL AND ${t.customName} IS NOT NULL)`,
    ),
  ],
);

/** Link opens per UTC day and source. Totals only: no IP, no user agent, never matched to a review. */
export const reviewLinkClicks = pgTable(
  "review_link_clicks",
  {
    orgId: orgId(),
    linkId: uuid("link_id")
      .notNull()
      .references(() => reviewLinks.id, { onDelete: "cascade" }),
    day: date("day").notNull(),
    source: text("source", { enum: reviewLinkSources }).notNull(),
    count: integer("count").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.linkId, t.day, t.source] })],
);

export const reviewRequestCampaignStatuses = ["draft", "active", "cancelled"] as const;
export const reviewRequestRecipientStatuses = ["pending", "sent", "skipped", "failed"] as const;

/**
 * One email campaign asking customers of ONE location for a Google review. Every recipient gets
 * the same message and the same review link (no review gating). Subject and body are fixed once the
 * campaign starts, which is when the guardrails run on them.
 */
export const reviewRequestCampaigns = pgTable(
  "review_request_campaigns",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    subject: text("subject").notNull(),
    body: text("body").notNull(),
    /** At most one reminder, this many days after the first email, only to people who have not clicked. */
    reminderEnabled: boolean("reminder_enabled").notNull().default(true),
    reminderDays: smallint("reminder_days").notNull().default(3),
    status: text("status", { enum: reviewRequestCampaignStatuses }).notNull().default("draft"),
    startedAt: timestamp("started_at", { withTimezone: true }),
    createdBy: text("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check("review_request_campaigns_reminder_days_check", sql`${t.reminderDays} between 1 and 14`),
    index("review_request_campaigns_ws_idx").on(t.workspaceId, t.createdAt),
  ],
);

/** One customer in a campaign. Personal data (email, name). `link_token` is the opaque random value in this person's click and unsubscribe links. It must be readable to build each email, so it is not hashed; it grants nothing but those two links. */
export const reviewRequestRecipients = pgTable(
  "review_request_recipients",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    campaignId: uuid("campaign_id")
      .notNull()
      .references(() => reviewRequestCampaigns.id, { onDelete: "cascade" }),
    /** Lower case. */
    email: text("email").notNull(),
    name: text("name"),
    linkToken: text("link_token").notNull(),
    status: text("status", { enum: reviewRequestRecipientStatuses }).notNull().default("pending"),
    /** Why a recipient was skipped or failed: opted_out, no_review_link, send_failed. */
    reason: text("reason"),
    attempts: integer("attempts").notNull().default(0),
    sentAt: timestamp("sent_at", { withTimezone: true }),
    reminderAttempts: integer("reminder_attempts").notNull().default(0),
    reminderSentAt: timestamp("reminder_sent_at", { withTimezone: true }),
    reminderFailedAt: timestamp("reminder_failed_at", { withTimezone: true }),
    clickedAt: timestamp("clicked_at", { withTimezone: true }),
    clickCount: integer("click_count").notNull().default(0),
    optedOutAt: timestamp("opted_out_at", { withTimezone: true }),
    /** How the uploader says the contact was obtained (a key from core's LIST_SOURCES), who confirmed the acceptable-use rules, and when. */
    listSource: text("list_source"),
    listConfirmedBy: text("list_confirmed_by").references(() => users.id, { onDelete: "set null" }),
    listConfirmedAt: timestamp("list_confirmed_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    unique("review_request_recipients_campaign_email_unique").on(t.campaignId, t.email),
    unique("review_request_recipients_token_unique").on(t.linkToken),
    index("review_request_recipients_due_idx").on(t.status, t.sentAt),
  ],
);

/** Addresses that asked not to be emailed, per client (workspace), forever. */
export const reviewRequestOptouts = pgTable(
  "review_request_optouts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    email: text("email").notNull(),
    createdAt: createdAt(),
  },
  (t) => [unique("review_request_optouts_ws_email_unique").on(t.workspaceId, t.email)],
);

export const reviewReplyStatus = pgEnum("review_reply_status", [
  "draft",
  "pending_approval",
  "approved",
  "published",
  "failed",
  "blocked",
  "deleted",
  "superseded",
  "conflict",
]);

/**
 * One row per reply REVISION of a review (revision 1, 2, ...). Terminal rows are `published`
 * (until replaced), `superseded`, `deleted` and `conflict` (Google changed after the draft); at most ONE row per review is open (draft,
 * pending_approval, approved, blocked, failed), enforced by a partial unique index. `body` is
 * reply text and may be derived from patient reviews: it is never copied into audit rows,
 * notifications or logs. `guardrail_result` is the latest GuardrailResult (rule ids, severities,
 * messages, match offsets; matched text may quote the body, so treat the row like the body).
 */
export const reviewReplies = pgTable(
  "review_replies",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    reviewId: uuid("review_id")
      .notNull()
      .references(() => reviews.id, { onDelete: "cascade" }),
    revision: integer("revision").notNull(),
    body: text("body").notNull(),
    status: reviewReplyStatus("status").notNull().default("draft"),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdSurface: text("created_surface", { enum: ["ui", "mcp", "worker", "cli"] }).notNull(),
    submittedBy: text("submitted_by").references(() => users.id),
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    approvedBy: text("approved_by").references(() => users.id),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
    rejectedBy: text("rejected_by").references(() => users.id),
    rejectedAt: timestamp("rejected_at", { withTimezone: true }),
    rejectReason: text("reject_reason"),
    /** Set while a publish is queued (status approved); cleared by every other transition. */
    publishRequestedBy: text("publish_requested_by").references(() => users.id),
    publishRequestedAt: timestamp("publish_requested_at", { withTimezone: true }),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    failureReason: text("failure_reason"),
    /**
     * Google's reply (comment, update time) as we knew it when this revision was created; null =
     * no reply. The publish job compares Google's live reply to this to detect a reply made in the
     * Google UI after the draft was written.
     */
    baseReplyComment: text("base_reply_comment"),
    baseReplyUpdateTime: timestamp("base_reply_update_time", { withTimezone: true }),
    /** Set on `conflict`: Google's reply found at publish time (null comment = reply deleted). Reply text: treat like body. */
    conflictGoogleComment: text("conflict_google_comment"),
    conflictGoogleUpdateTime: timestamp("conflict_google_update_time", { withTimezone: true }),
    conflictDetectedAt: timestamp("conflict_detected_at", { withTimezone: true }),
    guardrailResult: jsonb("guardrail_result"),
    warningsAcknowledged: boolean("warnings_acknowledged").notNull().default(false),
    /**
     * The workspace's autoApproveMinStars at the moment the star rule approved this reply; null =
     * not auto-approved. Set on every submit, cleared by a manual approve. Not derivable from
     * approved_by: nothing clears approved_at/approved_by when a row goes approved -> blocked ->
     * draft and is submitted again.
     */
    autoApprovedMinStars: smallint("auto_approved_min_stars"),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("review_replies_review_revision_unique").on(t.reviewId, t.revision),
    uniqueIndex("review_replies_one_open_per_review")
      .on(t.reviewId)
      .where(sql`${t.status} in ('draft', 'pending_approval', 'approved', 'blocked', 'failed')`),
    index("review_replies_org_workspace_status_idx").on(t.orgId, t.workspaceId, t.status),
  ],
);

export const postStatus = pgEnum("post_status", [
  "draft",
  "pending_approval",
  "approved",
  "scheduled",
  "publishing",
  "published",
  "failed",
  "blocked",
  "cancelled",
]);

export const postTopicTypes = ["STANDARD", "EVENT", "OFFER", "ALERT"] as const;

/**
 * A Google Business Profile local post (composer, approval, schedule). `summary` and the jsonb
 * content columns are post text: they are never copied into audit rows, notifications or logs
 * (audit carries ids, lengths and sha256). `scheduled_for` is the NEXT due time (UTC) once the post
 * is `scheduled`; `occurrence` is the index of that next send (0 = the first), advanced after each
 * send of a recurring post. `recurrence` is `{ freq, interval, until?, count?, anchor }`; occurrence
 * n is computed from `anchor`, never chained. `guardrail_result` quotes post text in its match
 * offsets and messages: treat the row like the summary.
 */
export const posts = pgTable(
  "posts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdSurface: text("created_surface", { enum: ["ui", "mcp", "worker", "cli"] }).notNull(),
    topicType: text("topic_type", { enum: postTopicTypes }).notNull(),
    alertType: text("alert_type"),
    summary: text("summary").notNull().default(""),
    /** Sent to Google as languageCode. Not part of the guardrail subject (see posts/publish.ts). */
    language: text("language", { enum: postLanguages }).notNull().default("en"),
    cta: jsonb("cta"),
    event: jsonb("event"),
    offer: jsonb("offer"),
    media: jsonb("media")
      .notNull()
      .default(sql`'[]'::jsonb`),
    status: postStatus("status").notNull().default("draft"),
    scheduledFor: timestamp("scheduled_for", { withTimezone: true }),
    recurrence: jsonb("recurrence"),
    occurrence: integer("occurrence").notNull().default(0),
    guardrailResult: jsonb("guardrail_result"),
    warningsAcknowledged: boolean("warnings_acknowledged").notNull().default(false),
    submittedBy: text("submitted_by").references(() => users.id),
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    approvedBy: text("approved_by").references(() => users.id),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
    rejectedBy: text("rejected_by").references(() => users.id),
    rejectedAt: timestamp("rejected_at", { withTimezone: true }),
    rejectReason: text("reject_reason"),
    scheduledBy: text("scheduled_by").references(() => users.id),
    scheduledAt: timestamp("scheduled_at", { withTimezone: true }),
    cancelledBy: text("cancelled_by").references(() => users.id),
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("posts_org_workspace_status_idx").on(t.orgId, t.workspaceId, t.status),
    // The minute sweep: due scheduled posts.
    index("posts_due_idx")
      .on(t.scheduledFor)
      .where(sql`${t.status} = 'scheduled'`),
    // Search: ILIKE '%x%' on post text (pg_trgm).
    index("posts_summary_trgm_idx").using("gin", sql`${t.summary} gin_trgm_ops`),
  ],
);

export const postTargetStatus = ["pending", "published", "failed", "skipped", "deleted"] as const;

/**
 * One row per (post, location, occurrence): the per-location result of a send. `google_post_name`
 * is `accounts/{a}/locations/{l}/localPosts/{p}` once published. `error` is a reason code, never
 * Google's response body or post text.
 */
export const postTargets = pgTable(
  "post_targets",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    postId: uuid("post_id")
      .notNull()
      .references(() => posts.id, { onDelete: "cascade" }),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    occurrence: integer("occurrence").notNull().default(0),
    status: text("status", { enum: postTargetStatus }).notNull().default("pending"),
    googlePostName: text("google_post_name"),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    error: text("error"),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("post_targets_post_location_occurrence_unique").on(t.postId, t.locationId, t.occurrence),
    index("post_targets_org_location_idx").on(t.orgId, t.locationId),
  ],
);

export const postEditStatus = [
  "pending_approval",
  "applying",
  "applied",
  "partly_applied",
  "failed",
  "rejected",
  "cancelled",
] as const;

/**
 * A proposed edit to a post that is already published on Google. A published post is terminal
 * in `posts`, and about ten readers count `posts`/`post_targets`, so an edit is its own record:
 * pending_approval -> applying (approved; the worker patches every published target) -> applied,
 * partly_applied (some locations failed) or failed. `changed_fields` are the Google field names
 * (summary, callToAction, event, offer, media) that differ from the post, and become the
 * updateMask. `revision` is 1, 2, ... per post and keeps the Google idempotency keys unique.
 * `results` is [{ targetId, locationId, status: "applied" | "failed", error? }], written as the
 * worker goes, so a retry skips locations already done. At most one open (pending_approval or
 * applying) edit per post.
 */
export const postEdits = pgTable(
  "post_edits",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    postId: uuid("post_id")
      .notNull()
      .references(() => posts.id, { onDelete: "cascade" }),
    revision: integer("revision").notNull(),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdSurface: text("created_surface", { enum: ["ui", "mcp", "worker", "cli"] }).notNull(),
    summary: text("summary").notNull().default(""),
    cta: jsonb("cta"),
    event: jsonb("event"),
    offer: jsonb("offer"),
    media: jsonb("media")
      .notNull()
      .default(sql`'[]'::jsonb`),
    changedFields: text("changed_fields").array().notNull(),
    status: text("status", { enum: postEditStatus }).notNull().default("pending_approval"),
    guardrailResult: jsonb("guardrail_result"),
    warningsAcknowledged: boolean("warnings_acknowledged").notNull().default(false),
    approvedBy: text("approved_by").references(() => users.id),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
    rejectedBy: text("rejected_by").references(() => users.id),
    rejectedAt: timestamp("rejected_at", { withTimezone: true }),
    rejectReason: text("reject_reason"),
    cancelledBy: text("cancelled_by").references(() => users.id),
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    appliedAt: timestamp("applied_at", { withTimezone: true }),
    results: jsonb("results")
      .notNull()
      .default(sql`'[]'::jsonb`),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("post_edits_post_revision_unique").on(t.postId, t.revision),
    uniqueIndex("post_edits_one_open_per_post_idx")
      .on(t.postId)
      .where(sql`${t.status} in ('pending_approval', 'applying')`),
    index("post_edits_org_workspace_status_idx").on(t.orgId, t.workspaceId, t.status),
  ],
);

/**
 * A mirror of a location's Google media items (photos only), refreshed by the review sync, so
 * the public location page can show a gallery without calling Google. URLs only, never bytes
 * (bytes wait for file storage). Google-hosted URLs are not stable; the next sync replaces them.
 */
export const googleMedia = pgTable(
  "google_media",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    /** `accounts/{a}/locations/{l}/media/{key}` */
    googleMediaName: text("google_media_name").notNull().unique(),
    category: text("category"),
    description: text("description"),
    googleUrl: text("google_url").notNull(),
    thumbnailUrl: text("thumbnail_url"),
    widthPixels: integer("width_pixels"),
    heightPixels: integer("height_pixels"),
    googleCreatedAt: timestamp("google_created_at", { withTimezone: true }),
    syncedAt: timestamp("synced_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("google_media_org_location_idx").on(t.orgId, t.locationId)],
);

/**
 * A mirror of the local posts on a location's Google profile, filled by the post sync that runs
 * after each review sync. It exists so lists and counts can include posts made outside SynGMB
 * (Google UI, other tools); a SynGMB post is recognised by its name in `post_targets.google_post_name`.
 * Rows of posts Google no longer lists are deleted. Not a source of truth: Google is.
 */
export const googlePosts = pgTable(
  "google_posts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    /** `accounts/{a}/locations/{l}/localPosts/{p}` */
    googlePostName: text("google_post_name").notNull().unique(),
    topicType: text("topic_type").notNull(),
    /** Google's state (LIVE, PROCESSING, REJECTED); null when Google omits it, which counts as live. */
    state: text("state"),
    summary: text("summary").notNull().default(""),
    eventTitle: text("event_title"),
    mediaUrl: text("media_url"),
    searchUrl: text("search_url"),
    ctaType: text("cta_type"),
    ctaUrl: text("cta_url"),
    googleCreatedAt: timestamp("google_created_at", { withTimezone: true }),
    googleUpdatedAt: timestamp("google_updated_at", { withTimezone: true }),
    syncedAt: timestamp("synced_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("google_posts_org_location_idx").on(t.orgId, t.locationId)],
);

export const replyProfiles = ["general", "healthcare", "legal"] as const;

/**
 * Per-workspace reply settings (approval rules, profile and guardrail packs). One row per
 * workspace; a missing row means the defaults in core's `DEFAULT_WORKSPACE_REPLY_SETTINGS`.
 * `packs` holds only the optional packs (`hipaa`, `legal_ethics`); `universal` always runs.
 */
export const workspaceReplySettings = pgTable(
  "workspace_reply_settings",
  {
    workspaceId: uuid("workspace_id")
      .primaryKey()
      .references(() => workspaces.id),
    orgId: orgId(),
    profile: text("profile", { enum: replyProfiles }).notNull().default("general"),
    packs: text("packs")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    skipPositiveReviews: boolean("skip_positive_reviews").notNull().default(false),
    genericTemplatesOnly: boolean("generic_templates_only").notNull().default(false),
    staffNames: text("staff_names")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    /** 4 or 5 auto-approves replies to reviews rated at least this; null = always manual. */
    autoApproveMinStars: smallint("auto_approve_min_stars"),
    autoPublish: boolean("auto_publish").notNull().default(false),
    /** Who switched auto-approve on and when (express consent, logged). Both null while it is off; rows that were already on before this was recorded stay null. */
    autoApproveEnabledBy: text("auto_approve_enabled_by").references(() => users.id),
    autoApproveEnabledAt: timestamp("auto_approve_enabled_at", { withTimezone: true }),
    /** HIPAA rules: `block` (default) or `warn` (still needs explicit acknowledgement). */
    h2Severity: text("h2_severity", { enum: ["block", "warn"] })
      .notNull()
      .default("block"),
    /** Draft an AI reply when the review sync finds a new review. Off by default. */
    draftOnArrival: boolean("draft_on_arrival").notNull().default(false),
    /** The owner/admin who switched it on: the job acts as them (reply rows need a user). */
    draftOnArrivalBy: text("draft_on_arrival_by").references(() => users.id),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    updatedBy: text("updated_by").references(() => users.id),
  },
  (t) => [
    check(
      "workspace_reply_settings_auto_approve_min_stars_check",
      sql`${t.autoApproveMinStars} IS NULL OR ${t.autoApproveMinStars} IN (4, 5)`,
    ),
    check("workspace_reply_settings_h2_severity_check", sql`${t.h2Severity} IN ('block', 'warn')`),
  ],
);

/** Reply templates, per workspace. `generic` is computed from the body (no reviewer-specific variable). */
export const replyTemplates = pgTable(
  "reply_templates",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    name: text("name").notNull(),
    body: text("body").notNull(),
    generic: boolean("generic").notNull(),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [unique("reply_templates_workspace_id_name_unique").on(t.workspaceId, t.name)],
);

// ---------------------------------------------------------------------------
// Geo-grid (GG1-GG4). Tenant tables; every row carries org_id.
// ---------------------------------------------------------------------------
export const gridDriverIds = [
  "dataforseo_standard",
  "places_relevance",
  "dataforseo_serp",
] as const;
/** Scan speed: standard = normal queue, fast = DataForSEO high priority. */
export const gridSpeeds = ["standard", "fast"] as const;
export const gridSchedules = ["manual", "daily", "weekly", "monthly"] as const;
/** What an account can choose as the starting competitor refresh for new trackers. */
export const gridCompetitorRefreshDefaults = ["manual", "weekly"] as const;
/**
 * tracker: a managed location tracked over time. quick_scan: any business (a prospect), run by hand.
 * keyword_rank: a managed location's keywords checked as one Google search each (local pack + organic), grid_size 1.
 */
export const gridConfigKinds = ["tracker", "quick_scan", "keyword_rank"] as const;
export const gridRunStatuses = ["queued", "running", "done", "failed"] as const;
export const gridTaskStatuses = ["pending", "submitted", "received", "done", "failed"] as const;

/** One tracked business + keyword set + grid shape. A run is created per keyword. */
export const gridConfigs = pgTable(
  "grid_configs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    kind: text("kind", { enum: gridConfigKinds }).notNull().default("tracker"),
    /** Set for trackers; null for quick scans (a CHECK keeps the two in step with `kind`). */
    locationId: uuid("location_id").references(() => locations.id),
    keywords: text("keywords").array().notNull(),
    /** Keywords starred by the team (subset of `keywords`, same spelling). Shown first. */
    favoriteKeywords: text("favorite_keywords")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    /** Odd, 3..13. */
    gridSize: smallint("grid_size").notNull(),
    radiusM: integer("radius_m").notNull(),
    /** Grid centre. Locations carry no coordinates, so they live here. */
    centerLat: doublePrecision("center_lat").notNull(),
    centerLng: doublePrecision("center_lng").notNull(),
    /** Business being ranked: matched by place id when set, else by exact (case-insensitive) title. */
    targetName: text("target_name").notNull(),
    targetPlaceId: text("target_place_id"),
    /** keyword_rank only: the business's website domain (no scheme, no www), matched against organic results. */
    targetDomain: text("target_domain"),
    driverId: text("driver_id", { enum: gridDriverIds }).notNull(),
    schedule: text("schedule", { enum: gridSchedules }).notNull().default("manual"),
    active: boolean("active").notNull().default(true),
    lastScheduledAt: timestamp("last_scheduled_at", { withTimezone: true }),
    /** How often this tracker's top competitors' profiles are refreshed (their own schedule; "manual" = off). */
    competitorRefresh: text("competitor_refresh", { enum: gridSchedules })
      .notNull()
      .default("manual"),
    competitorRefreshedAt: timestamp("competitor_refreshed_at", { withTimezone: true }),
    /** Top competitors of the last refresh that were skipped because Google gave no place id. */
    competitorSkippedNoPlaceId: integer("competitor_skipped_no_place_id").notNull().default(0),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("grid_configs_org_idx").on(t.orgId),
    check(
      "grid_configs_grid_size_check",
      sql`(${t.kind} = 'keyword_rank' AND ${t.gridSize} = 1) OR (${t.kind} <> 'keyword_rank' AND ${t.gridSize} BETWEEN 3 AND 13 AND ${t.gridSize} % 2 = 1)`,
    ),
    check("grid_configs_radius_check", sql`${t.radiusM} > 0`),
    check(
      "grid_configs_kind_location_check",
      sql`(${t.kind} <> 'quick_scan') = (${t.locationId} IS NOT NULL)`,
    ),
    check(
      "grid_configs_quick_scan_manual_check",
      sql`${t.kind} <> 'quick_scan' OR ${t.schedule} = 'manual'`,
    ),
  ],
);

export const gridRuns = pgTable(
  "grid_runs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    configId: uuid("config_id")
      .notNull()
      .references(() => gridConfigs.id, { onDelete: "cascade" }),
    keyword: text("keyword").notNull(),
    /** Snapshot at request time, so later config edits do not rewrite history. */
    driverId: text("driver_id", { enum: gridDriverIds }).notNull(),
    status: text("status", { enum: gridRunStatuses }).notNull().default("queued"),
    /** Snapshot at request time: run with the org's own DataForSEO key, billed at cost, outside the resold budget cap. */
    byo: boolean("byo").notNull().default(false),
    /** Snapshot at request time: queue speed. Prices, budget, cap and credit checks use this speed's unit price. */
    speed: text("speed", { enum: gridSpeeds }).notNull().default("standard"),
    costEstimateUsd: numeric("cost_estimate_usd", { precision: 12, scale: 4 }).notNull(),
    costChargedUsd: numeric("cost_charged_usd", { precision: 12, scale: 4 }),
    /** Snapshot at request time: where this run's data comes from. Older rows are fixtures. */
    dataSource: text("data_source", { enum: ["fixture", "sandbox", "live"] })
      .notNull()
      .default("fixture"),
    /** points x DataForSEO unit price, no markup; counted by the platform cap until submit. */
    providerEstimateUsd: numeric("provider_estimate_usd", { precision: 12, scale: 4 })
      .notNull()
      .default("0"),
    /** What DataForSEO reported in task_post `cost` (sum over chunks). Null until submitted. */
    providerCostUsd: numeric("provider_cost_usd", { precision: 12, scale: 4 }),
    error: text("error"),
    requestedBy: text("requested_by").references(() => users.id),
    startedAt: timestamp("started_at", { withTimezone: true }),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index("grid_runs_config_idx").on(t.configId, t.createdAt)],
);

export const gridPoints = pgTable(
  "grid_points",
  {
    runId: uuid("run_id")
      .notNull()
      .references(() => gridRuns.id, { onDelete: "cascade" }),
    orgId: orgId(),
    row: smallint("row").notNull(),
    col: smallint("col").notNull(),
    lat: doublePrecision("lat").notNull(),
    lng: doublePrecision("lng").notNull(),
    /** null = not found in the top results (or not collected yet). */
    rank: integer("rank"),
    /** keyword_rank only: the business's website position in the organic results (null = not in the top results). */
    organicRank: integer("organic_rank"),
    organicUrl: text("organic_url"),
    top3: boolean("top3").notNull().default(false),
    competitors: jsonb("competitors")
      .notNull()
      .default(sql`'[]'::jsonb`),
  },
  (t) => [primaryKey({ columns: [t.runId, t.row, t.col] })],
);

/**
 * The competitors seen in a finished tracker run, one row per tracker + keyword + business + day
 * (a second run the same day replaces the row). Written when the run finishes; the changes view diffs
 * the latest day against the day before. The tracked business itself is never stored here.
 */
export const gridCompetitorSnapshots = pgTable(
  "grid_competitor_snapshots",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    configId: uuid("config_id")
      .notNull()
      .references(() => gridConfigs.id, { onDelete: "cascade" }),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    runId: uuid("run_id").references(() => gridRuns.id, { onDelete: "set null" }),
    keyword: text("keyword").notNull(),
    placeId: text("place_id").notNull(),
    title: text("title").notNull(),
    address: text("address"),
    snapshotDate: date("snapshot_date", { mode: "string" }).notNull(),
    /** The run's data source. Changes are only computed between snapshots of the same source. */
    dataSource: text("data_source", { enum: ["fixture", "sandbox", "live"] }).notNull(),
    /** Grid points where the business appeared, and its rank among those appearances. */
    appearances: integer("appearances").notNull(),
    avgRank: numeric("avg_rank", { precision: 6, scale: 2 }).notNull(),
    bestRank: integer("best_rank").notNull(),
    rating: numeric("rating", { precision: 3, scale: 1 }),
    reviewCount: integer("review_count"),
    /** Google categories from the Maps result of the scan. Null when the scan carried none. */
    category: text("category"),
    additionalCategories: text("additional_categories").array(),
    categoryIds: text("category_ids").array(),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("grid_competitor_snapshots_key").on(
      t.configId,
      t.keyword,
      t.placeId,
      t.snapshotDate,
      t.dataSource,
    ),
    index("grid_competitor_snapshots_org_idx").on(t.orgId),
  ],
);

/**
 * A competitor's Google Business Profile as DataForSEO reported it, one row per org, business,
 * data source and UTC day (a re-fetch the same day replaces it). Categories are
 * {primary, additional[], ids[]}. `posts_count` is how many of the most recent updates were returned
 * (capped at the requested depth), not a lifetime total. Changes are only computed between rows of one source.
 */
export const competitorProfiles = pgTable(
  "competitor_profiles",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    placeId: text("place_id").notNull(),
    title: text("title"),
    fetchedAt: timestamp("fetched_at", { withTimezone: true }).notNull().defaultNow(),
    fetchedOn: date("fetched_on", { mode: "string" }).notNull(),
    dataSource: text("data_source", { enum: ["fixture", "sandbox", "live"] }).notNull(),
    categories: jsonb("categories")
      .$type<{ primary: string | null; additional: string[]; ids: string[] }>()
      .notNull()
      .default(sql`'{"primary":null,"additional":[],"ids":[]}'::jsonb`),
    totalPhotos: integer("total_photos"),
    lastPostAt: timestamp("last_post_at", { withTimezone: true }),
    postsCount: integer("posts_count"),
    rating: numeric("rating", { precision: 3, scale: 1 }),
    reviewCount: integer("review_count"),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("competitor_profiles_key").on(t.orgId, t.placeId, t.dataSource, t.fetchedOn),
    index("competitor_profiles_org_place_idx").on(t.orgId, t.placeId),
  ],
);

/**
 * One DataForSEO Standard task per competitor and kind (business info, or recent updates),
 * polled by the profile sweep. `charged_usd` is what the org was charged for the task (cost + markup),
 * taken when it was accepted; it counts toward the org's monthly geo-grid budget.
 */
export const competitorProfileTasks = pgTable(
  "competitor_profile_tasks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    placeId: text("place_id").notNull(),
    title: text("title"),
    kind: text("kind", { enum: ["info", "updates"] }).notNull(),
    dataSource: text("data_source", { enum: ["fixture", "sandbox", "live"] }).notNull(),
    taskRef: text("task_ref").notNull(),
    status: text("status", { enum: ["submitted", "done", "failed"] })
      .notNull()
      .default("submitted"),
    fetchedOn: date("fetched_on", { mode: "string" }).notNull(),
    providerCostUsd: numeric("provider_cost_usd", { precision: 12, scale: 6 })
      .notNull()
      .default("0"),
    chargedUsd: numeric("charged_usd", { precision: 12, scale: 6 }).notNull().default("0"),
    error: text("error"),
    submittedAt: timestamp("submitted_at", { withTimezone: true }).notNull().defaultNow(),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    index("competitor_profile_tasks_org_idx").on(t.orgId, t.createdAt),
    index("competitor_profile_tasks_open_idx").on(t.status, t.submittedAt),
  ],
);

/**
 * AI search visibility, switched on per location (a missing row means off). The category and city are what
 * the prompts are built from; `last_checked_at` drives the weekly schedule.
 */
export const aiVisibilitySettings = pgTable(
  "ai_visibility_settings",
  {
    locationId: uuid("location_id")
      .primaryKey()
      .references(() => locations.id, { onDelete: "cascade" }),
    orgId: orgId(),
    enabled: boolean("enabled").notNull().default(false),
    category: text("category").notNull().default(""),
    city: text("city").notNull().default(""),
    engines: text("engines").array().notNull(),
    lastCheckedAt: timestamp("last_checked_at", { withTimezone: true }),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    updatedBy: text("updated_by").references(() => users.id),
  },
  (t) => [index("ai_visibility_settings_org_idx").on(t.orgId)],
);

/** One weekly (or manual) check of one location. `charged_usd` counts toward the org's monthly geo-grid budget. */
export const aiVisibilityRuns = pgTable(
  "ai_visibility_runs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    dataSource: text("data_source", { enum: ["fixture", "sandbox", "live"] }).notNull(),
    promptCount: smallint("prompt_count").notNull(),
    providerCostUsd: numeric("provider_cost_usd", { precision: 12, scale: 6 })
      .notNull()
      .default("0"),
    chargedUsd: numeric("charged_usd", { precision: 12, scale: 6 }).notNull().default("0"),
    error: text("error"),
    createdAt: createdAt(),
  },
  (t) => [
    index("ai_visibility_runs_location_idx").on(t.locationId, t.createdAt),
    index("ai_visibility_runs_org_idx").on(t.orgId, t.createdAt),
  ],
);

/** What one engine answered to one prompt in one run. */
export const aiVisibilityResults = pgTable(
  "ai_visibility_results",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    runId: uuid("run_id")
      .notNull()
      .references(() => aiVisibilityRuns.id, { onDelete: "cascade" }),
    engine: text("engine").notNull(),
    prompt: text("prompt").notNull(),
    mentioned: boolean("mentioned").notNull(),
    /** Order of first appearance among the businesses named (1 = first). Null when the business is not named. */
    position: smallint("position"),
    competitors: text("competitors").array().notNull(),
    sourceDomains: text("source_domains").array().notNull(),
    excerpt: text("excerpt").notNull().default(""),
    error: text("error"),
    createdAt: createdAt(),
  },
  (t) => [index("ai_visibility_results_run_idx").on(t.runId)],
);

/**
 * One driver task per grid point. For pingback drivers `token_hash` is sha256 of the per-task
 * secret embedded in the pingback URL; the secret itself is never stored.
 */
export const gridTasks = pgTable(
  "grid_tasks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    runId: uuid("run_id")
      .notNull()
      .references(() => gridRuns.id, { onDelete: "cascade" }),
    row: smallint("row").notNull(),
    col: smallint("col").notNull(),
    /** The driver's task id (DataForSEO task id), set after submit. */
    taskRef: text("task_ref"),
    tokenHash: text("token_hash").notNull(),
    status: text("status", { enum: gridTaskStatuses }).notNull().default("pending"),
    error: text("error"),
    /** When the provider accepted this task; the stale-task sweeper measures from here. */
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    receivedAt: timestamp("received_at", { withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("grid_tasks_task_ref_unique").on(t.taskRef),
    index("grid_tasks_run_idx").on(t.runId),
    index("grid_tasks_status_submitted_idx").on(t.status, t.submittedAt),
  ],
);

/** Per-org geo-grid scan settings. A missing row means the defaults in core's config/geogrid. */
export const orgGridSettings = pgTable("org_grid_settings", {
  orgId: uuid("org_id")
    .primaryKey()
    .references(() => organizations.id),
  monthlyBudgetUsd: numeric("monthly_budget_usd", { precision: 12, scale: 2 }).notNull(),
  markupPercent: numeric("markup_percent", { precision: 6, scale: 2 }).notNull(),
  /** Speed for scheduled runs, and the pre-selected speed on manual runs. */
  defaultSpeed: text("default_speed", { enum: gridSpeeds }).notNull().default("standard"),
  /** The competitor refresh a NEW tracker starts with ("manual" = off). Changing it never touches existing trackers. */
  defaultCompetitorRefresh: text("default_competitor_refresh", {
    enum: gridCompetitorRefreshDefaults,
  })
    .notNull()
    .default("manual"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  updatedBy: text("updated_by").references(() => users.id),
});

// ---------------------------------------------------------------------------
// AI foundation. Tenant tables; every row carries org_id.
// ---------------------------------------------------------------------------
/** Brand voice and the optional monthly AI cap of one client. No row = defaults and no per-client cap. */
export const workspaceAiSettings = pgTable("workspace_ai_settings", {
  workspaceId: uuid("workspace_id")
    .primaryKey()
    .references(() => workspaces.id),
  orgId: orgId(),
  tone: text("tone").notNull().default(""),
  bannedWords: text("banned_words")
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  signOff: text("sign_off").notNull().default(""),
  /** Language the drafts are written in. Empty = the language of the source text. */
  language: text("language").notNull().default(""),
  /** Monthly cap for this client in micro-USD (1 USD = 1,000,000). Null = no per-client cap. */
  monthlyCapMicroUsd: bigint("monthly_cap_micro_usd", { mode: "number" }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  updatedBy: text("updated_by").references(() => users.id),
});

/** One row per model call that was made, written the moment the model answers. Never holds prompt or output text. */
export const aiUsage = pgTable(
  "ai_usage",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    userId: text("user_id").references(() => users.id),
    action: text("action").notNull(),
    purpose: text("purpose").notNull(),
    model: text("model").notNull(),
    inputTokens: integer("input_tokens").notNull(),
    outputTokens: integer("output_tokens").notNull(),
    costMicroUsd: bigint("cost_micro_usd", { mode: "number" }).notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    index("ai_usage_created_idx").on(t.createdAt),
    index("ai_usage_workspace_idx").on(t.workspaceId, t.createdAt),
  ],
);

// ---------------------------------------------------------------------------
// Review topics and sentiment. Tenant tables; every row carries org_id.
// ---------------------------------------------------------------------------
export const reviewTopicStatuses = ["classified", "unclassified"] as const;
/**
 * What the model made of one review: its topics with a sentiment each, and an overall sentiment. Holds NO
 * review text (healthcare reviews included): only a hash of the text it was made from, so an edited review
 * is classified again and an unchanged one never is. `unclassified` = the model's answer for it was unusable
 * twice; it keeps the hash, so it is not paid for again until the text changes or a person runs it again.
 */
export const reviewTopics = pgTable(
  "review_topics",
  {
    reviewId: uuid("review_id")
      .primaryKey()
      .references(() => reviews.id, { onDelete: "cascade" }),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    status: text("status", { enum: reviewTopicStatuses }).notNull(),
    /** positive | negative | mixed; null when unclassified. */
    overallSentiment: text("overall_sentiment"),
    /** [{ topic, sentiment }] with ids from core's REVIEW_TOPICS. */
    topics: jsonb("topics")
      .$type<{ topic: string; sentiment: string }[]>()
      .notNull()
      .default(sql`'[]'::jsonb`),
    model: text("model").notNull(),
    /** sha256 (hex) of reviews.comment as it was when classified. */
    textHash: text("text_hash").notNull(),
    classifiedAt: timestamp("classified_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("review_topics_workspace_idx").on(t.workspaceId),
    index("review_topics_location_idx").on(t.locationId),
    index("review_topics_topics_gin_idx").using("gin", t.topics),
  ],
);

/** Whether the daily sweep classifies a client's new reviews. No row = off: nobody is billed by surprise. */
export const workspaceReviewTopicSettings = pgTable("workspace_review_topic_settings", {
  workspaceId: uuid("workspace_id")
    .primaryKey()
    .references(() => workspaces.id),
  orgId: orgId(),
  autoClassify: boolean("auto_classify").notNull().default(false),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  updatedBy: text("updated_by").references(() => users.id),
});

// ---------------------------------------------------------------------------
// Performance snapshots and reports (PR1-PR3). Tenant tables; every row carries org_id.
// ---------------------------------------------------------------------------
export const reportScopes = ["workspace", "locations", "group"] as const;
export const reportKinds = ["performance", "reviews"] as const;
export const reportLanguages = ["en", "es"] as const;
export const reportPeriods = ["last_month", "last_30_days", "custom"] as const;
export const reportSchedules = ["none", "monthly"] as const;
export const reportRunStatuses = ["queued", "running", "done", "failed"] as const;
export const reportRunTriggers = ["manual", "schedule"] as const;

const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "bytea",
});

/**
 * Business Profile Performance API daily metrics, one row per location, day and DailyMetric.
 * Kept indefinitely (Google only serves ~18 months); never deleted by the app.
 */
export const performanceDaily = pgTable(
  "performance_daily",
  {
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    date: date("date", { mode: "string" }).notNull(),
    metric: text("metric").notNull(),
    value: integer("value").notNull(),
    capturedAt: timestamp("captured_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.locationId, t.date, t.metric] }),
    index("performance_daily_org_idx").on(t.orgId),
  ],
);

/**
 * Monthly search keywords (impressions, unique users). `month` is the first day of the month.
 * Google hides small counts: then `value` is null and `threshold` says the real value is below it.
 */
export const searchKeywordsMonthly = pgTable(
  "search_keywords_monthly",
  {
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    month: date("month", { mode: "string" }).notNull(),
    keyword: text("keyword").notNull(),
    value: integer("value"),
    threshold: integer("threshold"),
    capturedAt: timestamp("captured_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.locationId, t.month, t.keyword] }),
    index("search_keywords_monthly_org_idx").on(t.orgId),
    check(
      "search_keywords_monthly_value_or_threshold",
      sql`num_nonnulls(${t.value}, ${t.threshold}) = 1`,
    ),
  ],
);

/** Per-location snapshot progress: a row exists once the initial backfill has completed. */
export const performanceSnapshots = pgTable("performance_snapshots", {
  locationId: uuid("location_id")
    .primaryKey()
    .references(() => locations.id),
  orgId: orgId(),
  backfilledAt: timestamp("backfilled_at", { withTimezone: true }).notNull(),
  lastSnapshotDate: date("last_snapshot_date", { mode: "string" }).notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * OPS2: Google refused (403 PERMISSION_DENIED) to share one kind of data for a location with the
 * connected account. One row per (location, resource) while it is refused; skipped until
 * last_checked_at + the recheck window, deleted when a call works again.
 */
export const locationDataAccess = pgTable(
  "location_data_access",
  {
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id, { onDelete: "cascade" }),
    resource: text("resource").notNull(),
    orgId: orgId(),
    reason: text("reason").notNull(),
    firstSeenAt: timestamp("first_seen_at", { withTimezone: true }).notNull().defaultNow(),
    lastCheckedAt: timestamp("last_checked_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.locationId, t.resource] })],
);

export const reportDefinitions = pgTable(
  "report_definitions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    name: text("name").notNull(),
    /** performance (calls, clicks, keywords) or reviews (counts, ratings, reply rate; never review text). Fixed at creation. */
    kind: text("kind", { enum: reportKinds }).notNull().default("performance"),
    scope: text("scope", { enum: reportScopes }).notNull(),
    /** Used when scope = 'locations'; empty for a whole-workspace report. */
    locationIds: uuid("location_ids")
      .array()
      .notNull()
      .default(sql`'{}'::uuid[]`),
    /** Used when scope = 'group': its members are read when each run is generated. */
    groupId: uuid("group_id").references(() => locationGroups.id, { onDelete: "set null" }),
    period: text("period", { enum: reportPeriods }).notNull(),
    /** Only for period = 'custom'. */
    customFrom: date("custom_from", { mode: "string" }),
    customTo: date("custom_to", { mode: "string" }),
    schedule: text("schedule", { enum: reportSchedules }).notNull().default("none"),
    recipients: text("recipients")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    /** { agencyName, colour } shown on the PDF. */
    branding: jsonb("branding")
      .notNull()
      .default(sql`'{}'::jsonb`),
    /** Language of the PDF's labels and headings (the comment is not translated). */
    language: text("language", { enum: reportLanguages }).notNull().default("en"),
    /** Shown at the end of the report. Normalised and at most 500 characters (core enforces). */
    comment: text("comment"),
    /** Opt-in AI summary at the top of each run's report. Off by default; each summary is charged like an AI draft. */
    aiSummary: boolean("ai_summary").notNull().default(false),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("report_definitions_org_idx").on(t.orgId, t.workspaceId)],
);

export const reportRuns = pgTable(
  "report_runs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    definitionId: uuid("definition_id")
      .notNull()
      .references(() => reportDefinitions.id, { onDelete: "cascade" }),
    periodStart: date("period_start", { mode: "string" }).notNull(),
    periodEnd: date("period_end", { mode: "string" }).notNull(),
    status: text("status", { enum: reportRunStatuses }).notNull().default("queued"),
    trigger: text("trigger", { enum: reportRunTriggers }).notNull().default("manual"),
    /** The rendered PDF, size-capped by config. bytea for simplicity. */
    pdf: bytea("pdf"),
    pdfBytes: integer("pdf_bytes"),
    /**
     * What the PDF showed (figures, keywords, comment, branding), for the public share page.
     * Written with the PDF; null for runs made before it existed. Never review text.
     */
    content: jsonb("content"),
    /** The AI summary shown in the PDF, on the share page and in the email. Null when there is none. */
    summary: text("summary"),
    /** Null = no summary was tried (off, or not yet); else written, rejected, ai_off, over_cap, no_credit or ai_error. Set once, so a retried job never pays twice. */
    summaryStatus: text("summary_status"),
    error: text("error"),
    requestedBy: text("requested_by").references(() => users.id),
    /** Scheduled runs: set once the recipients have been emailed. */
    emailedAt: timestamp("emailed_at", { withTimezone: true }),
    createdAt: createdAt(),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
  },
  (t) => [
    index("report_runs_definition_idx").on(t.definitionId, t.createdAt),
    // One scheduled run per definition per period: the monthly job is idempotent.
    uniqueIndex("report_runs_schedule_unique")
      .on(t.definitionId, t.periodStart, t.periodEnd)
      .where(sql`${t.trigger} = 'schedule'`),
  ],
);

/** A public share link. Only sha256(token) is stored; the token is shown once. */
export const reportShareLinks = pgTable(
  "report_share_links",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    reportRunId: uuid("report_run_id")
      .notNull()
      .references(() => reportRuns.id, { onDelete: "cascade" }),
    tokenHash: text("token_hash").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    /** null for links the monthly schedule creates. */
    createdBy: text("created_by").references(() => users.id),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("report_share_links_token_hash_unique").on(t.tokenHash)],
);

/**
 * Bring-your-own DataForSEO key (HTTP Basic login + API password). The password is AES-GCM
 * ciphertext (core crypto.encryptSecret); it is never returned by any action.
 */
export const orgDataforseoCredentials = pgTable("org_dataforseo_credentials", {
  orgId: uuid("org_id")
    .primaryKey()
    .references(() => organizations.id),
  login: text("login").notNull(),
  passwordEnc: text("password_enc").notNull(),
  createdBy: text("created_by")
    .notNull()
    .references(() => users.id),
  createdAt: createdAt(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  lastVerifiedAt: timestamp("last_verified_at", { withTimezone: true }),
});

export const profileChangeSetStatus = pgEnum("profile_change_set_status", [
  "draft",
  "pending_approval",
  "approved",
  "queued",
  "applied",
  "partially_applied",
  "failed",
  "blocked",
  "cancelled",
]);

/**
 * One profile edit (the desired values in `fields`) applied to 1..N locations of a workspace; a
 * bulk edit is simply N targets. `fields` is business information (hours, description, ...), not
 * patient data, so it lives here; audit rows still carry only field names, masks, counts, rule ids
 * and a sha256. `update_mask` is the UNION of the Google field-mask entries over the targets (each
 * target stores its own minimal mask in `diff`). `draft` is part of the lifecycle but unused today:
 * propose goes straight to `blocked` or `pending_approval`.
 */
export const profileChangeSets = pgTable(
  "profile_change_sets",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdSurface: text("created_surface", { enum: ["ui", "mcp", "worker", "cli"] }).notNull(),
    status: profileChangeSetStatus("status").notNull().default("draft"),
    fields: jsonb("fields").notNull(),
    updateMask: text("update_mask")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    guardrailResult: jsonb("guardrail_result"),
    submittedAt: timestamp("submitted_at", { withTimezone: true }),
    approvedBy: text("approved_by").references(() => users.id),
    approvedAt: timestamp("approved_at", { withTimezone: true }),
    rejectedBy: text("rejected_by").references(() => users.id),
    rejectedAt: timestamp("rejected_at", { withTimezone: true }),
    rejectReason: text("reject_reason"),
    appliedRequestedBy: text("applied_requested_by").references(() => users.id),
    appliedRequestedAt: timestamp("applied_requested_at", { withTimezone: true }),
    cancelledBy: text("cancelled_by").references(() => users.id),
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("profile_change_sets_org_workspace_status_idx").on(t.orgId, t.workspaceId, t.status),
  ],
);

export const profileTargetStatus = [
  "pending",
  "applied",
  "failed",
  "skipped",
  "no_change",
] as const;

/**
 * The per-location part of a change set. `before` is the snapshot of the masked fields as the
 * preview saw them (the conflict check compares Google's live values with it), `after` the desired
 * values of those fields, `diff` the per-field changes plus this location's updateMask and
 * attributeMask. `error` is a reason code (`conflict`, `guardrail_blocked:<rules>`, `google_http_<n>`),
 * never Google's response body.
 */
export const profileChangeTargets = pgTable(
  "profile_change_targets",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    changeSetId: uuid("change_set_id")
      .notNull()
      .references(() => profileChangeSets.id, { onDelete: "cascade" }),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    status: text("status", { enum: profileTargetStatus }).notNull().default("pending"),
    before: jsonb("before").notNull(),
    after: jsonb("after").notNull(),
    diff: jsonb("diff").notNull(),
    error: text("error"),
    appliedAt: timestamp("applied_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("profile_change_targets_set_location_unique").on(t.changeSetId, t.locationId),
    index("profile_change_targets_org_location_idx").on(t.orgId, t.locationId),
  ],
);

/** White-label branding for one organization (agency name, https logo URL, two #rrggbb colours). */
export const orgBranding = pgTable(
  "org_branding",
  {
    orgId: uuid("org_id")
      .primaryKey()
      .references(() => organizations.id),
    agencyName: text("agency_name"),
    logoUrl: text("logo_url"),
    primaryColor: text("primary_color"),
    accentColor: text("accent_color"),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    updatedBy: text("updated_by").references(() => users.id),
  },
  (t) => [
    check(
      "org_branding_primary_hex",
      sql`${t.primaryColor} IS NULL OR ${t.primaryColor} ~ '^#[0-9a-f]{6}$'`,
    ),
    check(
      "org_branding_accent_hex",
      sql`${t.accentColor} IS NULL OR ${t.accentColor} ~ '^#[0-9a-f]{6}$'`,
    ),
    check("org_branding_logo_https", sql`${t.logoUrl} IS NULL OR ${t.logoUrl} LIKE 'https://%'`),
  ],
);

// ---------------------------------------------------------------------------
// Profile change watch, media and place action writes, suspension cases.
// ---------------------------------------------------------------------------

export const profileSnapshotSources = ["nightly", "push", "manual"] as const;

/**
 * The editable profile of a location as the MERCHANT view (what `locations.get` returns, normalised
 * the way change sets compare values), stored only when its hash differs from the previous one.
 * Never the consumer view from getGoogleUpdated: storing that would make the next nightly diff
 * report Google's own suggestion as a merchant change.
 */
export const profileSnapshots = pgTable(
  "profile_snapshots",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    takenAt: timestamp("taken_at", { withTimezone: true }).notNull().defaultNow(),
    source: text("source", { enum: profileSnapshotSources }).notNull(),
    data: jsonb("data").notNull(),
    /** sha256 of the canonical JSON of `data`. */
    hash: text("hash").notNull(),
  },
  (t) => [index("profile_snapshots_location_taken_idx").on(t.locationId, t.takenAt)],
);

export const profileChangeStatuses = ["open", "accepted", "reverted", "dismissed"] as const;

/**
 * A difference found between two merchant-view snapshots (`source` nightly/manual) or between the
 * merchant's profile and what Google shows consumers (`source` push, `google_suggested`). `before`
 * and `after` are ProfileValues for the changed fields only (business information, not patient
 * data); audit rows and notifications carry field NAMES only. `revert_change_set_id` is the earlier
 * change set that restores `before`; it goes through approval and the guarded apply path.
 */
export const profileChanges = pgTable(
  "profile_changes",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    detectedAt: timestamp("detected_at", { withTimezone: true }).notNull().defaultNow(),
    source: text("source", { enum: profileSnapshotSources }).notNull(),
    fieldPaths: text("field_paths").array().notNull(),
    before: jsonb("before").notNull(),
    after: jsonb("after").notNull(),
    googleSuggested: boolean("google_suggested").notNull().default(false),
    status: text("status", { enum: profileChangeStatuses }).notNull().default("open"),
    resolvedBy: text("resolved_by").references(() => users.id),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
    revertChangeSetId: uuid("revert_change_set_id").references(() => profileChangeSets.id),
  },
  (t) => [index("profile_changes_org_location_status_idx").on(t.orgId, t.locationId, t.status)],
);

/**
 * Per-location switches for undoing outside edits to the business name, phone and address
 * during the nightly profile watch. One row per location that was ever configured; no row means
 * everything off. `enabled_by` is the owner/admin who last saved it: the auto-revert acts with that
 * person's standing approval (a change set needs a real user), and is skipped if they lose access.
 */
export const locationAutoRevert = pgTable("location_auto_revert", {
  locationId: uuid("location_id")
    .primaryKey()
    .references(() => locations.id, { onDelete: "cascade" }),
  orgId: orgId(),
  name: boolean("name").notNull().default(false),
  phone: boolean("phone").notNull().default(false),
  address: boolean("address").notNull().default(false),
  enabledBy: text("enabled_by").references(() => users.id, { onDelete: "set null" }),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

/** Per-location marker that the customer-photo baseline has been taken (first scan notifies nothing). */
export const customerMediaScans = pgTable("customer_media_scans", {
  locationId: uuid("location_id")
    .primaryKey()
    .references(() => locations.id),
  orgId: orgId(),
  lastRunAt: timestamp("last_run_at", { withTimezone: true }).notNull(),
});

/** Customer media resource names already seen at a location; the unique key makes alerts once-only. */
export const customerMediaSeen = pgTable(
  "customer_media_seen",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    mediaName: text("media_name").notNull(),
    firstSeenAt: timestamp("first_seen_at", { withTimezone: true }).notNull().defaultNow(),
    /** null for the baseline scan, which does not notify. */
    notifiedAt: timestamp("notified_at", { withTimezone: true }),
  },
  (t) => [unique("customer_media_seen_location_media_unique").on(t.locationId, t.mediaName)],
);

export const locationOpDomains = ["media", "place_action", "food_menu"] as const;
export const locationOpKinds = ["add", "update", "delete"] as const;
/**
 * `scheduled` = a photo upload waiting for `scheduled_for`; the minute sweep turns it into `pending`.
 * `cancelled` = a scheduled upload the user cancelled before the sweep claimed it (terminal).
 */
export const locationOpStatuses = [
  "scheduled",
  "pending",
  "applied",
  "failed",
  "cancelled",
] as const;

/**
 * One asynchronous Google write for a location that is not a profile change set: a photo added or
 * deleted, a place action link created, updated or deleted. The action records it and enqueues a
 * job in one transaction; the worker calls Google through the guarded publish module with the
 * idempotency key `<domain>:<id>`. `payload` is the request (URL, category, ...); audit rows never
 * carry it (a URL can hold a signed token), only ids, kind, category and the URL's host.
 */
export const locationWriteOps = pgTable(
  "location_write_ops",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    domain: text("domain", { enum: locationOpDomains }).notNull(),
    kind: text("kind", { enum: locationOpKinds }).notNull(),
    payload: jsonb("payload").notNull(),
    status: text("status", { enum: locationOpStatuses }).notNull().default("pending"),
    /** A reason code (`google_http_<n>`, `location_inactive` ...), never Google's body. */
    error: text("error"),
    /** What Google returned (the created media name / link name). */
    result: jsonb("result"),
    requestedBy: text("requested_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    appliedAt: timestamp("applied_at", { withTimezone: true }),
    /** An instant: when a `scheduled` op becomes due. Null for an op that is sent at once. */
    scheduledFor: timestamp("scheduled_for", { withTimezone: true }),
    /** Ties together the per-location ops of one photo sent to several locations. */
    batchId: uuid("batch_id"),
  },
  (t) => [
    index("location_write_ops_org_location_idx").on(t.orgId, t.locationId, t.createdAt),
    index("location_write_ops_batch_idx").on(t.batchId),
    index("location_write_ops_due_idx").on(t.status, t.scheduledFor),
  ],
);

export const mediaUploadStatuses = ["pending", "uploaded", "failed", "purged"] as const;

/**
 * Photo bytes staged for a direct upload to Google (a phone or the MCP). NOT a photo store: the
 * bytes are kept only until Google accepts the upload (then `bytes` is set to NULL and status
 * becomes `uploaded`); a failed or abandoned upload's bytes are purged after a retention window
 * (status `purged`). The row itself (filename, size, sha256, pixels) stays as the record.
 */
export const mediaUploads = pgTable(
  "media_uploads",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    filename: text("filename").notNull(),
    contentType: text("content_type").notNull(),
    byteSize: integer("byte_size").notNull(),
    sha256: text("sha256").notNull(),
    width: integer("width").notNull(),
    height: integer("height").notNull(),
    bytes: bytea("bytes"),
    status: text("status", { enum: mediaUploadStatuses }).notNull().default("pending"),
    createdAt: createdAt(),
    purgedAt: timestamp("purged_at", { withTimezone: true }),
  },
  (t) => [index("media_uploads_status_created_idx").on(t.status, t.createdAt)],
);

/**
 * The per-workspace Media library for Google posts. Unlike `media_uploads` this IS a store: the
 * bytes stay until a person deletes the image. Google fetches a post's image from a public URL, so
 * each row has an unguessable `token` (48 hex chars) served at /m/<token>. `purgeStaleMediaUploads`
 * must never touch this table. Never copy `name` into audit rows.
 */
export const postImages = pgTable(
  "post_images",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    name: text("name").notNull(),
    token: text("token").notNull(),
    contentType: text("content_type").notNull(),
    byteSize: integer("byte_size").notNull(),
    width: integer("width").notNull(),
    height: integer("height").notNull(),
    sha256: text("sha256").notNull(),
    bytes: bytea("bytes").notNull(),
    /** Where the image came from. "upload" covers uploads and branded renders. */
    source: text("source", { enum: ["upload", "stock", "ai"] })
      .notNull()
      .default("upload"),
    /** Stock only: photographer name and the photo's page, shown as "Image by X from Pixabay". */
    creditName: text("credit_name"),
    creditUrl: text("credit_url"),
    /** AI only: the app labels these as AI-made. */
    aiGenerated: boolean("ai_generated").notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [
    unique("post_images_token_unique").on(t.token),
    index("post_images_workspace_created_idx").on(t.workspaceId, t.createdAt),
  ],
);

export const storedFileKinds = ["logo", "report_asset", "post_image_template"] as const;

/**
 * File store: small binary assets (logos first) kept in Postgres so the nightly backup and the
 * Drive sync already cover them. `workspace_id` null means the organization's own file (the agency
 * logo); set means one client's. One logo per slot (org or client); the same bytes uploaded again
 * into the same slot are one row (dedupe by sha256). Counts toward the organization's storage quota.
 */
export const storedFiles = pgTable(
  "stored_files",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id").references(() => workspaces.id),
    kind: text("kind", { enum: storedFileKinds }).notNull(),
    contentType: text("content_type").notNull(),
    byteSize: integer("byte_size").notNull(),
    sha256: text("sha256").notNull(),
    bytes: bytea("bytes").notNull(),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
  },
  (t) => [
    index("stored_files_org_workspace_idx").on(t.orgId, t.workspaceId),
    uniqueIndex("stored_files_dedupe_unique").on(
      t.orgId,
      t.kind,
      sql`coalesce(${t.workspaceId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      t.sha256,
    ),
    uniqueIndex("stored_files_logo_slot_unique")
      .on(t.orgId, sql`coalesce(${t.workspaceId}, '00000000-0000-0000-0000-000000000000'::uuid)`)
      .where(sql`${t.kind} = 'logo'`),
  ],
);

export const postTemplateTypes = ["STANDARD", "EVENT", "OFFER"] as const;

/**
 * A reusable starting point for a post: no locations, no send time, no event dates. "Use template"
 * only prefills Compose; a post made from it is an ordinary draft with no link back. `summary` is
 * post text: never copy it into audit rows.
 */
export const postTemplates = pgTable(
  "post_templates",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    name: text("name").notNull(),
    topicType: text("topic_type", { enum: postTemplateTypes }).notNull(),
    language: text("language", { enum: postLanguages }).notNull().default("en"),
    summary: text("summary").notNull().default(""),
    cta: jsonb("cta"),
    eventTitle: text("event_title"),
    offer: jsonb("offer"),
    imageId: uuid("image_id").references(() => postImages.id, { onDelete: "set null" }),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    updatedBy: text("updated_by")
      .notNull()
      .references(() => users.id),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [unique("post_templates_workspace_name_unique").on(t.workspaceId, t.name)],
);

export const suspensionCaseStatuses = ["open", "appealed", "reinstated", "closed_lost"] as const;

/** A suspension / reinstatement case for a location: evidence checklist, dates, outcome. Manual process. */
export const suspensionCases = pgTable(
  "suspension_cases",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    locationId: uuid("location_id")
      .notNull()
      .references(() => locations.id),
    openedAt: timestamp("opened_at", { withTimezone: true }).notNull().defaultNow(),
    reason: text("reason").notNull(),
    status: text("status", { enum: suspensionCaseStatuses }).notNull().default("open"),
    appealSubmittedAt: timestamp("appeal_submitted_at", { withTimezone: true }),
    outcomeAt: timestamp("outcome_at", { withTimezone: true }),
    outcomeNotes: text("outcome_notes"),
    /** [{ key, label, done, note }] */
    evidenceChecklist: jsonb("evidence_checklist").notNull(),
    createdBy: text("created_by")
      .notNull()
      .references(() => users.id),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("suspension_cases_org_location_idx").on(t.orgId, t.locationId, t.status)],
);

export const mcpProposalStatuses = [
  "pending",
  "applied",
  "expired",
  "cancelled",
  "failed",
] as const;

/**
 * Two-phase MCP writes: a write tool called over MCP stores its (parsed) input here and returns a
 * preview; `mcp.proposals.apply` re-validates and executes it exactly once. Bound to the API token,
 * user and organisation that created it.
 */
export const mcpProposals = pgTable(
  "mcp_proposals",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    tokenId: uuid("token_id")
      .notNull()
      .references(() => apiTokens.id),
    userId: text("user_id")
      .notNull()
      .references(() => users.id),
    action: text("action").notNull(),
    input: jsonb("input").notNull(),
    /** sha256 of the canonical JSON of `input`; apply refuses a row whose input no longer hashes to it. */
    inputHash: text("input_hash").notNull(),
    preview: jsonb("preview").notNull(),
    status: text("status", { enum: mcpProposalStatuses }).notNull().default("pending"),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: createdAt(),
    appliedAt: timestamp("applied_at", { withTimezone: true }),
    result: jsonb("result"),
    error: text("error"),
  },
  (t) => [index("mcp_proposals_org_token_idx").on(t.orgId, t.tokenId, t.createdAt)],
);

export const jobRunStatuses = ["running", "ok", "failed"] as const;

/**
 * One row per run of a scheduled background job (worker), so System status can show the last run
 * and its result after pg-boss has deleted its own job rows (7 days). Server-wide: no org column.
 * `note` and `error` never carry tenant data (no names, no counts).
 */
export const jobRuns = pgTable(
  "job_runs",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    /** A key of SYSTEM_JOBS in packages/core/src/system-jobs.ts. */
    job: text("job").notNull(),
    startedAt: timestamp("started_at", { withTimezone: true }).notNull(),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
    status: text("status", { enum: jobRunStatuses }).notNull(),
    note: text("note"),
    /** "CODE: message", at most 300 characters. */
    error: text("error"),
  },
  (t) => [index("job_runs_job_started_idx").on(t.job, t.startedAt)],
);

/**
 * Monitoring. Platform-wide (no organization): one row per distinct server error, keyed by a
 * fingerprint of where it came from and what it said. `message` is already stripped of secrets,
 * emails and ids. `lastAlertedAt` is what limits an alert to one email per fingerprint per window.
 */
export const errorEvents = pgTable(
  "error_events",
  {
    fingerprint: text("fingerprint").primaryKey(),
    source: text("source", { enum: ["web", "worker", "mcp"] }).notNull(),
    message: text("message").notNull(),
    count: integer("count").notNull().default(1),
    firstSeenAt: timestamp("first_seen_at", { withTimezone: true }).notNull(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull(),
    lastAlertedAt: timestamp("last_alerted_at", { withTimezone: true }),
  },
  (t) => [index("error_events_last_seen_idx").on(t.lastSeenAt)],
);

/** Small named values the monitors share (worker heartbeat, worker-down flag, job-failure cursor). */
export const monitorState = pgTable("monitor_state", {
  key: text("key").primaryKey(),
  value: text("value"),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull(),
});

/**
 * OPS1: counters per (scope, kind, period). Scope is an organization id (per-account daily caps, period
 * a UTC day) or "platform" (events per UTC hour, such as Google per-org limit hits and email failures).
 */
export const limitCounters = pgTable(
  "limit_counters",
  {
    scope: text("scope").notNull(),
    kind: text("kind").notNull(),
    period: text("period").notNull(),
    count: integer("count").notNull().default(0),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.scope, t.kind, t.period] })],
);

/** Google API calls per UTC day and client method, counted at the throttled client (retries included). */
export const googleApiCalls = pgTable(
  "google_api_calls",
  {
    day: date("day", { mode: "string" }).notNull(),
    method: text("method").notNull(),
    calls: integer("calls").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.day, t.method] })],
);

/**
 * Outgoing webhook subscriptions (G7a). `secret_enc` is the Standard Webhooks signing secret,
 * encrypted at rest because the worker must read it back to sign; the plaintext is shown once on
 * create and never listed or audited. A null `workspace_id` means organization-wide.
 */
export const webhookSubscriptions = pgTable(
  "webhook_subscriptions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id").references(() => workspaces.id, { onDelete: "cascade" }),
    url: text("url").notNull(),
    events: text("events").array().notNull(),
    secretEnc: text("secret_enc").notNull(),
    description: text("description"),
    createdByUserId: text("created_by_user_id")
      .notNull()
      .references(() => users.id),
    apiTokenId: uuid("api_token_id").references(() => apiTokens.id),
    status: text("status", { enum: ["active", "disabled"] })
      .notNull()
      .default("active"),
    disabledReason: text("disabled_reason", {
      enum: ["gone", "failing", "token_revoked", "creator_removed", "manual"],
    }),
    consecutiveFailures: integer("consecutive_failures").notNull().default(0),
    createdAt: createdAt(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("webhook_subscriptions_org_status_idx").on(t.orgId, t.status)],
);

/**
 * One row per (subscription, event, entity) to send. `id` is the Standard Webhooks `webhook-id`
 * and stays the same across retries. Payload carries review text, so rows are purged after 30 days.
 */
export const webhookDeliveries = pgTable(
  "webhook_deliveries",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    orgId: orgId(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id),
    subscriptionId: uuid("subscription_id")
      .notNull()
      .references(() => webhookSubscriptions.id, { onDelete: "cascade" }),
    eventType: text("event_type").notNull(),
    entityId: text("entity_id").notNull(),
    payload: jsonb("payload").notNull(),
    test: boolean("test").notNull().default(false),
    status: text("status", { enum: ["pending", "delivered", "failed", "skipped"] })
      .notNull()
      .default("pending"),
    attempts: integer("attempts").notNull().default(0),
    lastStatusCode: integer("last_status_code"),
    lastError: text("last_error"),
    createdAt: createdAt(),
    deliveredAt: timestamp("delivered_at", { withTimezone: true }),
  },
  (t) => [
    uniqueIndex("webhook_deliveries_event_unique")
      .on(t.subscriptionId, t.eventType, t.entityId)
      .where(sql`${t.test} = false`),
    index("webhook_deliveries_subscription_created_idx").on(t.subscriptionId, t.createdAt.desc()),
  ],
);
